INSERT INTO stickers (
  code, canonical_code, album_id, album_order, source_sheet, source_row, context_name,
  section_id, team_id, sticker_type_code, subject, sticker_number, initial_quantity, initial_owned
)
SELECT
  source_stickers.code,
  source_stickers.canonical_code,
  albums.id,
  source_stickers.album_order,
  source_stickers.source_sheet,
  source_stickers.source_row,
  source_stickers.context_name,
  sticker_sections.id,
  teams.id,
  source_stickers.sticker_type_code,
  source_stickers.subject,
  source_stickers.sticker_number,
  source_stickers.initial_quantity,
  source_stickers.initial_owned
FROM source_stickers
JOIN albums ON albums.slug = 'panini-fifa-world-cup-2026'
LEFT JOIN sticker_sections ON source_stickers.context_kind = 'section' AND sticker_sections.name = source_stickers.context_name
LEFT JOIN teams ON source_stickers.context_kind = 'team' AND teams.name = source_stickers.context_name
ON CONFLICT (code) DO UPDATE SET
  canonical_code = EXCLUDED.canonical_code,
  album_id = EXCLUDED.album_id,
  album_order = EXCLUDED.album_order,
  source_sheet = EXCLUDED.source_sheet,
  source_row = EXCLUDED.source_row,
  context_name = EXCLUDED.context_name,
  section_id = EXCLUDED.section_id,
  team_id = EXCLUDED.team_id,
  sticker_type_code = EXCLUDED.sticker_type_code,
  subject = EXCLUDED.subject,
  sticker_number = EXCLUDED.sticker_number,
  initial_quantity = EXCLUDED.initial_quantity,
  initial_owned = EXCLUDED.initial_owned;

COMMIT;
